/**
 * Extracts creation timestamp from template object via createdAt, updatedAt, or ID digits
 */
function getTimestampFromTemplate(tpl) {
  if (!tpl) return 0;
  
  if (typeof tpl.createdAt === 'number' && tpl.createdAt > 0) {
    return tpl.createdAt;
  }
  
  if (tpl.createdAt && typeof tpl.createdAt === 'string' && !isNaN(Date.parse(tpl.createdAt))) {
    return Date.parse(tpl.createdAt);
  }
  
  if (tpl.updatedAt && typeof tpl.updatedAt === 'string' && !isNaN(Date.parse(tpl.updatedAt))) {
    return Date.parse(tpl.updatedAt);
  }
  
  if (tpl.id && typeof tpl.id === 'string') {
    const match = tpl.id.match(/\d{10,}/);
    if (match) return parseInt(match[0], 10);
  }

  return 0;
}

/**
 * Sorts templates by Creation Time descending (Newest Created First)
 */
function sortTemplatesNewestFirst(templatesList) {
  if (!Array.isArray(templatesList)) return [];
  return templatesList.slice().sort((a, b) => {
    return getTimestampFromTemplate(b) - getTimestampFromTemplate(a);
  });
}

function sanitizeForFirestore(obj) {
  const clean = {};
  for (const key in obj) {
    if (obj[key] !== undefined && obj[key] !== null) {
      if (typeof obj[key] === 'object' && !Array.isArray(obj[key])) {
        clean[key] = sanitizeForFirestore(obj[key]);
      } else {
        clean[key] = obj[key];
      }
    }
  }
  return clean;
}

function getCategories() {
  const data = localStorage.getItem(CATEGORIES_KEY);
  if (!data) {
    localStorage.setItem(CATEGORIES_KEY, JSON.stringify(DEFAULT_CATEGORIES));
    return DEFAULT_CATEGORIES;
  }
  try {
    const parsed = JSON.parse(data);
    if (!Array.isArray(parsed) || parsed.length === 0) {
      return DEFAULT_CATEGORIES;
    }
    return parsed;
  } catch (e) {
    return DEFAULT_CATEGORIES;
  }
}

function saveCategories(cats) {
  if (Array.isArray(cats) && cats.length > 0) {
    localStorage.setItem(CATEGORIES_KEY, JSON.stringify(cats));
    window.cachedCategories = cats;

    const db = window.getDb ? window.getDb() : null;
    if (db) {
      db.collection('web_config').doc('categories').set({ items: cats }).catch(e => console.warn(e));
    }
  }
}

window.cachedCategories = getCategories();

function generateCleanSlugId(text) {
  return text
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/đ/g, 'd').replace(/Đ/g, 'D')
    .replace(/[^a-zA-Z0-9\s-]/g, '')
    .trim()
    .replace(/\s+/g, '-');
}

async function apiAddCategory(name) {
  const cats = getCategories();
  const cleanName = name.trim();
  let slugId = generateCleanSlugId(cleanName) || ('cat-' + Date.now());

  let uniqueId = slugId;
  let counter = 1;
  while (cats.some(c => c.id === uniqueId)) {
    uniqueId = `${slugId}-${counter}`;
    counter++;
  }

  const newCat = { id: uniqueId, name: cleanName };
  cats.push(newCat);
  saveCategories(cats);
  return cats;
}

async function apiUpdateCategory(id, name) {
  const cats = getCategories();
  const idx = cats.findIndex(c => c.id === id);
  if (idx !== -1) {
    cats[idx].name = name.trim();
    saveCategories(cats);
  }
  return cats;
}

async function apiDeleteCategory(id) {
  if (id === 'All') return getCategories();
  let cats = getCategories();
  cats = cats.filter(c => c.id !== id);
  saveCategories(cats);
  return cats;
}

function getLocalTemplates() {
  const data = localStorage.getItem(STORAGE_KEY);
  if (!data) {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(DEFAULT_TEMPLATES));
    return sortTemplatesNewestFirst(DEFAULT_TEMPLATES);
  }
  try {
    const parsed = JSON.parse(data);
    if (!Array.isArray(parsed) || parsed.length === 0) {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(DEFAULT_TEMPLATES));
      return sortTemplatesNewestFirst(DEFAULT_TEMPLATES);
    }
    return sortTemplatesNewestFirst(parsed);
  } catch (e) {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(DEFAULT_TEMPLATES));
    return sortTemplatesNewestFirst(DEFAULT_TEMPLATES);
  }
}

function saveLocalTemplates(templates) {
  if (Array.isArray(templates) && templates.length > 0) {
    const sorted = sortTemplatesNewestFirst(templates);
    localStorage.setItem(STORAGE_KEY, JSON.stringify(sorted));
  }
}

window.cachedTemplates = getLocalTemplates();

/**
 * Direct Live Firebase Firestore Fetch Engine
 * Fetches all templates in web_templates collection directly from Firebase Cloud and sorts strictly BY CREATION TIME DESCENDING.
 */
async function fetchTemplatesFromAPI() {
  const db = window.getDb ? window.getDb() : null;
  if (db) {
    try {
      const catDoc = await db.collection('web_config').doc('categories').get();
      if (catDoc.exists && catDoc.data().items) {
        window.cachedCategories = catDoc.data().items;
        saveCategories(catDoc.data().items);
      }
    } catch (e) {
      console.warn("Categories fetch notice:", e.message);
    }

    try {
      const snapshot = await db.collection('web_templates').get();
      if (!snapshot.empty) {
        const fbTemplates = [];
        snapshot.forEach(doc => {
          fbTemplates.push({ id: doc.id, ...doc.data() });
        });
        // Force overwrite MelodyFlow Studio with latest room.html in Firebase Cloud Database
        const melodyTpl = DEFAULT_TEMPLATES.find(t => t.id === 'tpl-melodyflow-studio');
        if (melodyTpl) {
          try {
            const sanitized = sanitizeForFirestore(melodyTpl);
            db.collection('web_templates').doc('tpl-melodyflow-studio').set(sanitized).catch(() => {});
            const idx = fbTemplates.findIndex(t => t.id === 'tpl-melodyflow-studio');
            if (idx !== -1) fbTemplates[idx] = sanitized;
            else fbTemplates.unshift(sanitized);
          } catch(e) {}
        }

        if (fbTemplates.length > 0) {
          const sortedFB = sortTemplatesNewestFirst(fbTemplates);
          window.cachedTemplates = sortedFB;
          saveLocalTemplates(sortedFB);
          console.log(`🔥 Synchronized ${sortedFB.length} live products (Strict Creation Time Order) directly from Firebase Cloud Database!`);
          return sortedFB;
        }
      }
    } catch (err) {
      console.warn("Firebase Firestore fetch templates notice:", err.message);
    }
  }

  window.cachedTemplates = getLocalTemplates();
  return window.cachedTemplates;
}

async function apiAddTemplate(templateData) {
  const now = Date.now();
  const id = templateData.id || ('tpl-' + now);
  templateData.id = id;
  templateData.createdAt = now;
  templateData.updatedAt = new Date().toISOString().split('T')[0];

  const sanitized = sanitizeForFirestore(templateData);

  // 1. Instant local update (0.001s)
  window.cachedTemplates.unshift(sanitized);
  window.cachedTemplates = sortTemplatesNewestFirst(window.cachedTemplates);
  saveLocalTemplates(window.cachedTemplates);
  if (window.AdminManager) {
    window.AdminManager.showNotification(`Đã đăng bài "${templateData.title}" thành công!`, "success");
  }

  // 2. Background async sync to Firebase Cloud (non-blocking)
  const db = window.getDb ? window.getDb() : null;
  if (db) {
    db.collection('web_templates').doc(id).set(sanitized)
      .then(() => console.log("🔥 Cloud synced:", id))
      .catch(err => console.warn("Firebase sync notice:", err.message));
  }

  return sanitized;
}

async function apiUpdateTemplate(id, templateData) {
  templateData.id = id;
  const existing = window.cachedTemplates.find(t => t.id === id);
  if (existing && existing.createdAt) {
    templateData.createdAt = existing.createdAt;
  } else {
    const match = id.match(/\d{10,}/);
    templateData.createdAt = match ? parseInt(match[0], 10) : Date.now();
  }
  templateData.updatedAt = new Date().toISOString().split('T')[0];

  const sanitized = sanitizeForFirestore(templateData);

  // 1. Instant local update (0.001s)
  const idx = window.cachedTemplates.findIndex(t => t.id === id);
  if (idx !== -1) window.cachedTemplates[idx] = sanitized;
  window.cachedTemplates = sortTemplatesNewestFirst(window.cachedTemplates);
  saveLocalTemplates(window.cachedTemplates);
  if (window.AdminManager) {
    window.AdminManager.showNotification("Đã cập nhật bài đăng thành công!", "success");
  }

  // 2. Background async sync to Firebase Cloud (non-blocking)
  const db = window.getDb ? window.getDb() : null;
  if (db) {
    db.collection('web_templates').doc(id).set(sanitized, { merge: true })
      .then(() => console.log("🔥 Cloud updated:", id))
      .catch(err => console.warn("Firebase update notice:", err.message));
  }

  return sanitized;
}

async function apiDeleteTemplate(id) {
  const db = window.getDb ? window.getDb() : null;
  if (db) {
    try {
      await db.collection('web_templates').doc(id).delete();
    } catch (err) {
      console.error("Firebase delete error", err);
    }
  }

  window.cachedTemplates = window.cachedTemplates.filter(t => t.id !== id);
  window.cachedTemplates = sortTemplatesNewestFirst(window.cachedTemplates);
  saveLocalTemplates(window.cachedTemplates);
  return window.cachedTemplates;
}

function getStoredTemplates() {
  const t = window.cachedTemplates;
  if (Array.isArray(t) && t.length > 0) return sortTemplatesNewestFirst(t);
  return getLocalTemplates();
}
